/* Animated pool water + fire pit for the footer photo (unsplash 1707190205120).
   Masks are drawn for that exact photo: if the photo changes, remove this script. */
(function(){
  const ft=document.querySelector('footer');
  if(!ft||matchMedia('(prefers-reduced-motion:reduce)').matches) return;
  if(!/1707190205120/.test(getComputedStyle(ft,'::after').backgroundImage)) return;
  const IW=2200,IH=1467,X0=780,Y0=790,CW=1020,CH=390,PX=.5,PY=.6; // PX/PY = background-position
  const cv=document.createElement('canvas');
  cv.id='footWater';
  cv.setAttribute('aria-hidden','true');
  cv.style.cssText='position:absolute;z-index:-2;pointer-events:none;opacity:0;transition:opacity 1s';
  const gl=cv.getContext('webgl',{premultipliedAlpha:true,alpha:true,antialias:false});
  if(!gl) return;
  const VS='attribute vec2 p;varying vec2 u;void main(){u=vec2(p.x*.5+.5,.5-p.y*.5);gl_Position=vec4(p,0.,1.);}';
  const FS=`
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
varying vec2 u;uniform sampler2D im,mk;uniform float t;
float h(vec2 p){p=mod(p,289.);vec3 q=fract(vec3(p.xyx)*.1031);q+=dot(q,q.yzx+33.33);return fract((q.x+q.y)*q.z);}
float n(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(h(i),h(i+vec2(1,0)),f.x),mix(h(i+vec2(0,1)),h(i+vec2(1,1)),f.x),f.y)-.5;}
float wave(vec2 P){return n(P+vec2(t*.4,t*.9))+n(P*1.9+vec2(-t*.7,t*1.1)+7.)*.6+n(P*3.7+vec2(t*1.1,-t)+19.)*.3;}
void main(){
  vec2 sz=vec2(1020.,390.);
  vec2 px=vec2(780.,790.)+u*sz;
  vec3 m=texture2D(mk,u).rgb;
  float a=max(m.r,max(m.g,m.b));
  if(a<.01){gl_FragColor=vec4(0.);return;}
  vec3 c=texture2D(im,u).rgb;
  // pool
  if(m.r>.01){
    float H=max(px.y-760.,60.);
    vec2 P=vec2((px.x-1150.)/H*7.,4200./H);
    float w=wave(P),wx=wave(P+vec2(.35,0.))-w,wz=wave(P+vec2(0.,.35))-w;
    float near=clamp((px.y-850.)/300.,0.,1.);
    vec2 d=vec2((px.x-1066.)/42.,(px.y-853.)/16.);
    float r=length(vec2(max(abs(d.x)-.5,0.),d.y));
    float ring=sin(r*7.-t*5.)*exp(-r*.5);
    vec2 off=vec2(wx*mix(7.,20.,near),wz*mix(5.,13.,near)+ring*1.8)/sz;
    vec2 q=u+off*smoothstep(.2,.9,texture2D(mk,u+off).r)*m.r;
    vec3 pool=texture2D(im,q).rgb;
    pool*=1.+wz*.3+w*.06+ring*.08;
    // light caustics on the lit floor
    float ca=1.-abs(wave(P*.8+4.))*3.2;
    pool+=vec3(.35,.75,.8)*smoothstep(.35,1.,ca)*.2;
    c=mix(c,pool,m.r);
  }
  // fire: flames drawn over a plate with the photo's still flames removed
  float fk=n(vec2(t*3.1,3.))+n(vec2(t*7.3,9.))*.5;
  vec2 e=vec2((px.x-1612.)/42.,0.);
  float yb=868.+(px.x-1572.)*.105;
  float y=(yb-px.y)/62.;
  if(m.g>.01){
    float sway=n(vec2(px.y*.03+t*1.6,5.))*9.*clamp(y,0.,1.);
    float X=px.x+sway;
    float nn=n(vec2(X*.085,px.y*.04+t*2.6))+n(vec2(X*.19+7.,px.y*.08+t*4.3))*.6+n(vec2(X*.4+3.,px.y*.16+t*6.5))*.25;
    float ex=(X-1612.)/40.;
    float env=sqrt(max(1.-ex*ex,0.))*(.78+n(vec2(X*.05,t*1.3))*.45+fk*.1);
    float heat=env-y*.95+nn*(.35+y*1.1);
    float base=smoothstep(-.06,.03,y);
    float f=smoothstep(.02,.42,heat)*base*smoothstep(1.1,.85,y);
    vec3 col=mix(vec3(.95,.3,.04),vec3(1.,.66,.1),smoothstep(.05,.4,heat));
    col=mix(col,vec3(1.,.95,.72),smoothstep(.38,.85,heat+(.25-y)*.35));
    c=mix(c,col,f*m.g);
  }
  // flickering glow on the pit and chairs
  c+=c*vec3(1.,.55,.2)*m.b*(fk*.5+.06);
  gl_FragColor=vec4(clamp(c,0.,1.)*a,a);
}`;
  const sh=(k,s)=>{const o=gl.createShader(k);gl.shaderSource(o,s);gl.compileShader(o);if(!gl.getShaderParameter(o,gl.COMPILE_STATUS))console.error('Footer water:',gl.getShaderInfoLog(o));return o};
  const pr=gl.createProgram();gl.attachShader(pr,sh(gl.VERTEX_SHADER,VS));gl.attachShader(pr,sh(gl.FRAGMENT_SHADER,FS));gl.linkProgram(pr);
  if(!gl.getProgramParameter(pr,gl.LINK_STATUS)) return;
  gl.useProgram(pr);
  gl.bindBuffer(gl.ARRAY_BUFFER,gl.createBuffer());
  gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);
  const loc=gl.getAttribLocation(pr,'p');gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);
  const ut=gl.getUniformLocation(pr,'t');
  // same maths as background-size:cover, so the canvas stays locked to the photo
  function place(){
    const W=ft.clientWidth,H=ft.clientHeight,k=Math.max(W/IW,H/IH);
    cv.style.left=(W-IW*k)*PX+X0*k+'px';cv.style.top=(H-IH*k)*PY+Y0*k+'px';cv.style.width=CW*k+'px';cv.style.height=CH*k+'px';
    const w=Math.min(1200,Math.round(CW*k*Math.min(devicePixelRatio||1,2))),h=Math.round(w*CH/CW);
    if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h;gl.viewport(0,0,w,h)}
  }
  const load=s=>new Promise((ok,no)=>{const i=new Image();i.onload=()=>ok(i);i.onerror=no;i.src=s});
  Promise.all([load("data:image/webp;base64,"),load("data:image/webp;base64,")]).then(a=>{
    a.forEach((im,i)=>{
      gl.activeTexture(gl.TEXTURE0+i);gl.bindTexture(gl.TEXTURE_2D,gl.createTexture());
      gl.texImage2D(gl.TEXTURE_2D,0,gl.RGB,gl.RGB,gl.UNSIGNED_BYTE,im);
      [gl.TEXTURE_WRAP_S,gl.TEXTURE_WRAP_T].forEach(x=>gl.texParameteri(gl.TEXTURE_2D,x,gl.CLAMP_TO_EDGE));
      gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);
      gl.uniform1i(gl.getUniformLocation(pr,i?'mk':'im'),i);
    });
    ft.append(cv);place();
    new ResizeObserver(place).observe(ft);
    let on=false,id=0,last=0;
    function frame(ms){if(ms-last>30){last=ms;gl.uniform1f(ut,(ms/1000)%600);gl.drawArrays(gl.TRIANGLES,0,3)}id=on?requestAnimationFrame(frame):0}
    new IntersectionObserver(e=>{on=e[e.length-1].isIntersecting;if(on&&!id)id=requestAnimationFrame(frame)}).observe(cv);
    cv.addEventListener('webglcontextlost',()=>{on=false;cv.remove()});
    requestAnimationFrame(()=>cv.style.opacity=1);
  }).catch(e=>console.error('Footer water:',e));
})();
